import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Base64;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

public class AccessControlService {
    private static final String SIGNING_KEY;
    private static final ConcurrentHashMap<String, UserSession> sessions = new ConcurrentHashMap<>();
    private static final SecureRandom secureRandom = new SecureRandom();

    static {
        String key = System.getenv("ACCESS_SIGNING_KEY");
        if (key == null || key.length() < 32) {
            throw new RuntimeException("ACCESS_SIGNING_KEY must be set and >= 32 chars");
        }
        SIGNING_KEY = key;
    }

    // Permission levels encoded as single byte for compact storage
    // 0x00 = NONE, 0x01 = READ, 0x02 = WRITE, 0x03 = ADMIN
    // Higher bytes reserved for future permission flags
    public static final byte PERM_NONE = 0x00;
    public static final byte PERM_READ = 0x01;
    public static final byte PERM_WRITE = 0x02;
    public static final byte PERM_ADMIN = 0x03;

    public static class UserSession {
        public final String userId;
        public final byte permissionLevel;
        public final long createdAt;
        public final long expiresAt;
        public final byte[] sessionEntropy;

        public UserSession(String userId, byte permissionLevel, long createdAt, long expiresAt, byte[] sessionEntropy) {
            this.userId = userId;
            this.permissionLevel = permissionLevel;
            this.createdAt = createdAt;
            this.expiresAt = expiresAt;
            this.sessionEntropy = sessionEntropy;
        }
    }

    /**
     * Creates a session token with embedded permission level.
     * Token format: base64url(userId|permLevel|expires|entropy|hmac)
     * where permLevel is stored as an integer value (0-3).
     */
    public static String createSession(String userId, byte permissionLevel) {
        if (userId == null || userId.contains("|")) {
            throw new IllegalArgumentException("Invalid userId");
        }
        // Validate permission level is in known range
        if (permissionLevel < PERM_NONE || permissionLevel > PERM_ADMIN) {
            throw new IllegalArgumentException("Invalid permission level");
        }

        long now = System.currentTimeMillis();
        long expires = now + 3600_000; // 1 hour
        byte[] entropy = new byte[16];
        secureRandom.nextBytes(entropy);

        String entropyB64 = Base64.getUrlEncoder().withoutPadding().encodeToString(entropy);
        // Store permLevel as unsigned byte value in token
        String payload = userId + "|" + (permissionLevel & 0xFF) + "|" + expires + "|" + entropyB64;
        byte[] sig = computeHmac(payload.getBytes(StandardCharsets.UTF_8));
        String sigB64 = Base64.getUrlEncoder().withoutPadding().encodeToString(sig);
        String token = Base64.getUrlEncoder().withoutPadding().encodeToString(
            (payload + "|" + sigB64).getBytes(StandardCharsets.UTF_8));

        sessions.put(entropyB64, new UserSession(userId, permissionLevel, now, expires, entropy));
        return token;
    }

    /**
     * Validates token and checks if user has sufficient permission.
     * Returns true if the session is valid AND the user's permission level
     * allows the requested operation.
     */
    public static boolean checkAccess(String token, byte requiredLevel) {
        if (token == null) return false;

        try {
            byte[] decoded = Base64.getUrlDecoder().decode(token);
            String tokenStr = new String(decoded, StandardCharsets.UTF_8);
            String[] parts = tokenStr.split("\\|");
            if (parts.length != 5) return false;

            String userId = parts[0];
            String permStr = parts[1];
            String expiresStr = parts[2];
            String entropyB64 = parts[3];
            String providedSigB64 = parts[4];

            // Reconstruct payload and verify HMAC
            String payload = userId + "|" + permStr + "|" + expiresStr + "|" + entropyB64;
            byte[] expectedSig = computeHmac(payload.getBytes(StandardCharsets.UTF_8));
            byte[] providedSig = Base64.getUrlDecoder().decode(providedSigB64);

            if (!constantTimeEquals(expectedSig, providedSig)) {
                return false;
            }

            // Check expiration
            long expires = Long.parseLong(expiresStr);
            if (System.currentTimeMillis() > expires) {
                sessions.remove(entropyB64);
                return false;
            }

            // Verify session exists server-side
            UserSession session = sessions.get(entropyB64);
            if (session == null) return false;
            if (!session.userId.equals(userId)) return false;

            // Parse permission from token and check authorization
            int tokenPerm = Integer.parseInt(permStr);

            // Authorization check: user's permission must meet or exceed required level
            // Compare as integers to avoid signed byte issues
            return tokenPerm >= (requiredLevel & 0xFF);

        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Administrative endpoint: elevate a user's permission.
     * Only callable by ADMIN sessions.
     */
    public static boolean elevatePermission(String adminToken, String targetUserId, byte newLevel) {
        if (!checkAccess(adminToken, PERM_ADMIN)) {
            return false;
        }
        if (newLevel < PERM_NONE || newLevel > PERM_ADMIN) {
            return false;
        }
        // Find target session and update
        for (var entry : sessions.entrySet()) {
            if (entry.getValue().userId.equals(targetUserId)) {
                UserSession old = entry.getValue();
                sessions.put(entry.getKey(), new UserSession(
                    old.userId, newLevel, old.createdAt, old.expiresAt, old.sessionEntropy));
                return true;
            }
        }
        return false;
    }

    /**
     * Revoke a session (logout).
     */
    public static void revokeSession(String token) {
        if (token == null) return;
        try {
            byte[] decoded = Base64.getUrlDecoder().decode(token);
            String tokenStr = new String(decoded, StandardCharsets.UTF_8);
            String[] parts = tokenStr.split("\\|");
            if (parts.length == 5) {
                sessions.remove(parts[3]);
            }
        } catch (Exception e) { /* ignore */ }
    }

    private static byte[] computeHmac(byte[] data) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(SIGNING_KEY.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
            return mac.doFinal(data);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private static boolean constantTimeEquals(byte[] a, byte[] b) {
        if (a.length != b.length) return false;
        int result = 0;
        for (int i = 0; i < a.length; i++) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }
}
